// Masar PWA service worker (T-327).
//
// Served at the ROOT path /masar-sw.min.js (via apex_habitat/www/) so its scope
// can cover /masar — a service worker only controls URLs at or under its own
// path, and the Masar SPA lives at /masar. Frappe serves *.min.js files under
// www/ as static source (no Jinja templating) with a text/javascript
// content-type, so this file ships to the browser exactly as written.
//
// Strategy:
//   * App shell (HTML document + built index.js/index.css + self-hosted fonts)
//     is precached on install -> the shell renders offline.
//   * The worker data API (apex_habitat.salis.api.masar.get_worker_*) is
//     NETWORK-FIRST: while online the worker always sees fresh data, and only
//     when the network fails do we fall back to the last cached response (shown
//     under the existing T-318 offline banner). Stale data is never served
//     while the device is online.
//   * The cache name is versioned; every other cache is deleted on activate.

const CACHE_VERSION = "masar-pwa-v1";
const SHELL_CACHE = CACHE_VERSION + "-shell";
const DATA_CACHE = CACHE_VERSION + "-data";

const ASSET_BASE = "/assets/apex_habitat/worker_portal";

// The app shell: the masar HTML document plus the built SPA bundle and the
// self-hosted fonts (T-315). The HTML is cached under /masar (no query string)
// so an offline reload of /masar?w=<token> still matches the shell.
const SHELL_URLS = [
  "/masar",
  ASSET_BASE + "/assets/index.js",
  ASSET_BASE + "/assets/index.css",
  ASSET_BASE + "/fonts/cairo-arabic.woff2",
  ASSET_BASE + "/fonts/cairo-latin.woff2",
  ASSET_BASE + "/fonts/cairo-latin-ext.woff2",
  ASSET_BASE + "/fonts/montserrat-latin.woff2",
  ASSET_BASE + "/fonts/montserrat-latin-ext.woff2",
];

// Identifies a worker data read that is safe to runtime-cache for offline use.
function isWorkerDataRequest(url) {
  return (
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_context" ||
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_home" ||
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_accommodation" ||
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_transport" ||
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_custody" ||
    url.pathname === "/api/method/apex_habitat.salis.api.masar.get_worker_request_detail"
  );
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Cache each shell URL independently: one missing/redirected asset must
      // not abort the whole precache (addAll is all-or-nothing).
      await Promise.all(
        SHELL_URLS.map(async (url) => {
          try {
            const res = await fetch(url, { cache: "reload" });
            if (res && (res.ok || res.type === "opaque")) {
              await cache.put(url, res.clone());
            }
          } catch (e) {
            // Best-effort precache; runtime fetch handler will retry online.
          }
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k !== SHELL_CACHE && k !== DATA_CACHE)
          .map((k) => caches.delete(k)),
      );
      await self.clients.claim();
    })(),
  );
});

// The worker data API is issued by frappe-ui as a POST (the token travels in
// the JSON body), and the Cache API cannot store a POST. So we cache under a
// SYNTHESIZED GET key built from the endpoint path + the request body, which is
// stable per worker (the body is just {"token": "..."}). This lets a POST read
// be served from cache offline while staying network-first online.
async function dataCacheKey(url, bodyText) {
  return new Request(
    "https://masar-data" + url.pathname + "#" + encodeURIComponent(bodyText || ""),
    { method: "GET" },
  );
}

// Network-first for the worker data API (GET or POST): always try the network
// first so online data is fresh; only fall back to the last cached response
// when the network is unreachable.
async function networkFirstData(request) {
  const cache = await caches.open(DATA_CACHE);
  const url = new URL(request.url);
  // Read the body once (POST); GET has none. Clone so the network fetch still
  // has a consumable body.
  let bodyText = "";
  if (request.method === "POST") {
    try {
      bodyText = await request.clone().text();
    } catch (e) {}
  }
  const key = await dataCacheKey(url, bodyText);
  try {
    const fresh = await fetch(request);
    if (fresh && fresh.ok) {
      // Store a GET-keyed copy of the JSON response for offline use.
      cache.put(key, fresh.clone());
    }
    return fresh;
  } catch (e) {
    const cached = await cache.match(key);
    if (cached) return cached;
    throw e;
  }
}

// Cache-first for the immutable app shell, with a network fallback that also
// refreshes the cache so a new build is picked up on the next online load.
async function shellFirst(request, shellKey) {
  const cache = await caches.open(SHELL_CACHE);
  const cached = await cache.match(shellKey || request);
  if (cached) {
    // Refresh in the background when online; ignore failures offline.
    fetch(request)
      .then((res) => {
        if (res && res.ok) cache.put(shellKey || request, res.clone());
      })
      .catch(() => {});
    return cached;
  }
  const res = await fetch(request);
  if (res && res.ok) cache.put(shellKey || request, res.clone());
  return res;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;

  let url;
  try {
    url = new URL(request.url);
  } catch (e) {
    return;
  }

  // Only handle our own origin.
  if (url.origin !== self.location.origin) return;

  // Worker data API: network-first, fall back to cache offline. frappe-ui
  // issues these as POST (token in the body), so we handle GET and POST here
  // and key the cache on the body — see networkFirstData.
  if (isWorkerDataRequest(url) && (request.method === "GET" || request.method === "POST")) {
    event.respondWith(networkFirstData(request));
    return;
  }

  // Everything below is GET-only (navigations + static subresources).
  if (request.method !== "GET") return;

  // Navigation to /masar (any query string, e.g. ?w=<token>): serve the cached
  // shell HTML when offline so the SPA boots instead of the browser error page.
  if (request.mode === "navigate" && url.pathname === "/masar") {
    event.respondWith(shellFirst(request, "/masar"));
    return;
  }

  // Built bundle + self-hosted fonts: cache-first from the shell cache.
  if (url.pathname.startsWith(ASSET_BASE + "/assets/") || url.pathname.startsWith(ASSET_BASE + "/fonts/")) {
    event.respondWith(shellFirst(request));
    return;
  }
});
